def f(N: int, A: List[int], edges: List[Tuple[int, int]]) -> int:
    '''
    N: an integer
    A: a list of integers
    edges: a list of tuples of integers
    '''
    from collections import defaultdict
    graph = defaultdict(list)
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)
    max_sum = max(A)
    ans = 0
    for i in range(1, N+1):
        if A[i-1] > max_sum:
            for j in range(1, N+1):
                if A[j-1] == max_sum:
                    if i!= j:
                        ans += 2
                        break
        else:
            for j in graph[i]:
                if A[j-1] == A[i-1]:
                    ans += 2
                    break
    return ans
```

